  for (let run = 1; run <= 12; run++) {
    const arr = [];
    for (let v = 0; v < 20; v++) {
      for (let r = 0; r < run; r++) arr.push(v);
    }
    add('runs-of-' + run, arr);
  }

  const rand = rng(20261002);
  for (let trial = 0; trial < 80; trial++) {
    const len = Math.floor(rand() * 160);
    const arr = Array.from({ length: len }, () => Math.floor(rand() * 41) - 20).sort((a, b) => a - b);
