          return;
        }
        const failures = [];
        for (let i = 0; i < expected.length; i++) {
          if (!eq(parsed.results[i], expected[i])) failures.push(tests[i].name);
        }
        if (failures.length) finish({ accept: false, reason: 'failed cases: ' + failures.slice(0, 16).join(', ') });
        else finish({ accept: true, reason: 'pinned tests and oracle checks passed' });
      } catch {
        finish({ accept: false, reason: 'suite did not complete (no trustworthy result)' });
      }
    });
    try {
      child.stdin.write(payload);
      child.stdin.end();
    } catch {
      finish({ accept: false, reason: 'failed to send suite to worker' });
    }
  });

  return outcome;
}
