Turn 1 — called whoami({"address":"0x6313E6CA15F751D64C16BA72bC71dBAF35eBaE54"}) -> {"address":"0x6313E6CA15F751D64C16BA72bC71dBAF35eBaE54","isIssuer":true,"lots":[{"taskClass":"code","classId":"0x2dc081a8d6d4714c79b5abd2e9b08c3a33b4ef1dcf946ef8b8cf6c495014f47b","headroomMilliSiu":"35000","issuanceLimitMilliSiu":"48000"},{"taskClass":"extract","classId":"0xc3a71ae87b7c3ebddac6a71a0769398904aa1c025ba79ce83e237d582b484491","headroomMilliSiu":"48000","issuanceLimitMilliSiu":"48000"}]}
Turn 2 — called submit_job({"taskClass":"code","originalGate":{"taskClass":"code","source":"import { writeFileSync, mkdirSync } from "node:fs";
import { spawn } from "node:child_process";

const TEST_CASES = "test(\"dedupes an already-deduped array\", () => {\n  assert.deepStrictEqual(dedupeSorted([1, 2, 3]), [1, 2, 3]);\n});\n";
/**
 * How many cases this gate WROTE. Compared against how many actually reported a pass, because
 * those two numbers coming apart is the whole vulnerability below.
 */
const EXPECTED_CASES = 1;

export async function gate({ referenceDir, submissionDir }) {
  mkdirSync(referenceDir, { recursive: true });
  const testSource =
    'import { test } from "node:test";\n' +
    'import assert from "node:assert/strict";\n' +
    'import { dedupeSorted } from "' + submissionDir + '/answer.mjs";\n' +
    TEST_CASES;
  writeFileSync(referenceDir + "/test.mjs", testSource);

  const { code, output } = await new Promise((resolve) => {
    const child = spawn(process.execPath, ["--test", referenceDir + "/test.mjs"], { env: {} });
    let output = "";
    child.stdout.on("data", (c) => { output += c; });
    child.stderr.on("data", (c) => { output += c; });
    child.on("close", (code) => resolve({ code, output }));
    child.on("error", (e) => resolve({ code: -1, output: String(e) }));
  });

  // Matches both node:test's TAP reporter ("# pass N") and its default "spec" reporter
  // ("ℹ pass N") — found live, 2026-09-22: this Node version uses the latter, and the
  // TAP-only regex silently matched nothing, defaulting passes to 0 and rejecting every gate
  // regardless of the real outcome. Matching both rather than picking one avoids the same class
  // of bug reappearing on a different Node version (e.g. in CI) that defaults to the other.
  const passMatch = output.match(/(?:#|\u2139)\s*pass\s+(\d+)/);
  const failMatch = output.match(/(?:#|\u2139)\s*fail\s+(\d+)/);
  const passes = passMatch ? Number(passMatch[1]) : 0;
  const fails = failMatch ? Number(failMatch[1]) : (code === 0 ? 0 : 1);
  // `passes === EXPECTED_CASES`, not `passes > 0`. Found live 2026-09-30, from the real attack
  // in run 9: a submission whose module body called process.exit(0) ended the test child after
  // ONE case, and this gate reported "all 1 test case(s) passed" for a function returning [] for
  // every input. A partial run is a failed run. A gate that does not check that its own suite
  // executed completely is not grading — it is sampling whatever the submission allowed it to
  // reach, and the submission chooses how much that is.
  const accept = code === 0 && fails === 0 && passes === EXPECTED_CASES;
  return {
    accept,
    reason: accept
      ? `all ${EXPECTED_CASES} test case(s) passed`
      : `${fails} failed, ${passes} of ${EXPECTED_CASES} case(s) passed (exit ${code})`,
  };
}
"},"hardenedGate":{"taskClass":"code","source":"export async function gate({ referenceDir, submissionDir }) {
  const fs = await import('node:fs');
  const path = await import('node:path');
  const { spawn } = await import('node:child_process');
  const crypto = await import('node:crypto');
