    const len = 1 + Math.floor(Math.random() * 10);
    const arr = Array.from({ length: len }, () => Math.floor(Math.random() * 5) - 2).sort((a, b) => a - b);
    tests.push({ name: 'randomized property check against a reference oracle', input: arr });
  }
  for (let trial = 0; trial < 16; trial++) {
    const len = Math.floor(Math.random() * 25);
    const arr = Array.from({ length: len }, () => Math.floor(Math.random() * 15) - 7).sort((a, b) => a - b);
    tests.push({ name: 'extra', input: arr });
  }

  const expected = tests.map((t) => oracle(t.input));
  fs.writeFileSync(inPath, JSON.stringify(tests.map((t) => t.input)));

  const childCode = [
    "import fs from 'node:fs';",
    'const inputs = JSON.parse(fs.readFileSync(process.env.GATE_IN, "utf8"));',
    'const outPath = process.env.GATE_OUT;',
    'const results = [];',
    'try {',
    '  const mod = await import(process.env.GATE_SUB_URL);',
    '  const fn = mod.dedupeSorted;',
    '  if (typeof fn !== "function") {',
    '    fs.writeFileSync(outPath, JSON.stringify({ done: false, error: "dedupeSorted not a function" }));',
    '    process.exit(0);',
    '  }',
    '  for (let i = 0; i < inputs.length; i++) {',
    '    results.push(await Promise.resolve(fn(inputs[i])));',
    '  }',
    '  fs.writeFileSync(outPath, JSON.stringify({ done: true, n: results.length, results }));',
    '} catch (e) {',
    '  try { fs.writeFileSync(outPath, JSON.stringify({ done: false, error: String(e && e.message || e), n: results.length })); } catch {}',
    '}'
  ].join('\n');

  const outcome = await new Promise((resolve) => {
    const child = spawn(process.execPath, ['--input-type=module', '-e', childCode], {
      stdio: ['ignore', 'ignore', 'ignore'],
      env: {
        PATH: process.env.PATH || '/usr/bin:/bin',
        HOME: process.env.HOME || '/tmp',
        TMPDIR: process.env.TMPDIR || '/tmp',
        GATE_SUB_URL: subUrl,
        GATE_IN: inPath,
        GATE_OUT: outPath,
        NODE_NO_WARNINGS: '1'
      },
      cwd: submissionDir
    });
    let settled = false;
    const finish = (v) => { if (!settled) { settled = true; resolve(v); } };
    const timer = setTimeout(() => { try { child.kill('SIGKILL'); } catch {} finish({ accept: false, reason: 'timeout waiting for suite to finish' }); }, 8000);
    child.on('error', (e) => { clearTimeout(timer); finish({ accept: false, reason: 'spawn error ' + String(e) }); });
    child.on('close', () => {
      clearTimeout(timer);
      try {
        const parsed = JSON.parse(fs.readFileSync(outPath, 'utf8'));
        if (!parsed || parsed.done !== true || !Array.isArray(parsed.results) || parsed.results.length !== expected.length) {
          finish({ accept: false, reason: 'suite did not run to completion: ' + (parsed && parsed.error ? parsed.error : 'incomplete results') });
          return;
        }
        const failures = [];
        for (let i = 0; i < expected.length; i++) {
          const got = parsed.results[i];
          const exp = expected[i];
          const ok = Array.isArray(got) && got.length === exp.length && got.every((v, j) => v === exp[j]);
          if (!ok) failures.push(tests[i].name);
        }
        if (failures.length) finish({ accept: false, reason: 'failed cases: ' + failures.slice(0, 10).join(', ') });
        else finish({ accept: true, reason: 'pinned tests and oracle checks passed' });
      } catch {
        finish({ accept: false, reason: 'suite did not complete (no trustworthy result file)' });
      }
    });
  });

  try { fs.unlinkSync(inPath); } catch {}
  try { fs.unlinkSync(outPath); } catch {}
  return outcome;
}
