    '  const send = (o) => { process.stdout.write(p.nonce + JSON.stringify(o) + String.fromCharCode(10)); };',
    '  try {',
    '    const mod = await import(p.subUrl);',
    '    const fn = mod.dedupeSorted;',
    '    if (typeof fn !== "function") { send({ ok: false, error: "not a function" }); return; }',
    '    const results = [];',
    '    for (let i = 0; i < p.inputs.length; i++) {',
    '      const copy = p.inputs[i].slice();',
    '      let got = fn(copy);',
