  return await new Promise((resolve) => {
    const child = spawn(process.execPath, ['--input-type=module', '-e', childCode], {
      stdio: ['pipe', 'pipe', 'ignore'],
      env: { PATH: process.env.PATH || '/usr/bin:/bin', NODE_NO_WARNINGS: '1' },
      cwd: os.tmpdir(),
    });
