      clearTimeout(timer);
      try {
        const idx = out.lastIndexOf(nonce);
        if (idx < 0) { finish({ accept: false, reason: 'no result' }); return; }
        const parsed = JSON.parse(out.slice(idx + nonce.length).split('\n')[0]);
        if (!parsed || parsed.ok !== true || !Array.isArray(parsed.results) || parsed.results.length !== expected.length) {
