            }
          }
          if (!ok) { finish({ accept: false, reason: 'fail ' + JSON.stringify(tests[i]) }); return; }
        }
        finish({ accept: true, reason: 'oracle checks passed' });
      } catch {
        finish({ accept: false, reason: 'unreadable result' });
      }
    });
    child.stdin.end(payload);
  });
}
